const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define countries
  const countries = ee.FeatureCollection('FAO/GAUL/2015/level0');
  const namibia = countries.filter(ee.Filter.eq('ADM0_NAME', 'Namibia'));
  const zimbabwe = countries.filter(ee.Filter.eq('ADM0_NAME', 'Zimbabwe'));

  // Load MODIS NDVI data
  const modis = ee.ImageCollection('MODIS/006/MOD13Q1')
    .select('NDVI');

  // Function to filter Feb 21-28 period
  function filterFebPeriod(collection) {
    return collection.filter(ee.Filter.calendarRange(2, 2, 'month'))
                    .filter(ee.Filter.calendarRange(21, 28, 'day_of_month'));
  }

  // Target period (2019)
  const target2019 = filterFebPeriod(modis.filterDate('2019-02-01', '2019-02-28'));

  // Baseline period (2003-2017)
  const baseline = filterFebPeriod(modis.filterDate('2003-02-01', '2017-02-28'));

  // Check data availability
  const targetCount = target2019.size().getInfo();
  const baselineCount = baseline.size().getInfo();

  print(`Target 2019 images: ${targetCount}, Baseline images: ${baselineCount}`);

  if (targetCount === 0 || baselineCount === 0) {
    print("<answer>C1</answer>");
    return;
  }

  // Calculate baseline mean NDVI for each country
  const baselineMean = baseline.mean().multiply(0.0001); // Scale factor for MODIS NDVI

  // Calculate 2019 mean NDVI for each country
  const target2019Mean = target2019.mean().multiply(0.0001);

  // Function to calculate anomaly and stats
  function calculateAnomalyStats(country, countryName) {
    const baselineVal = baselineMean.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: country,
      scale: 1000,
      maxPixels: 1e9
    }).get('NDVI');

    const targetVal = target2019Mean.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: country,
      scale: 1000,
      maxPixels: 1e9
    }).get('NDVI');

    const pixelCount = baselineMean.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: country,
      scale: 1000,
      maxPixels: 1e9
    }).get('NDVI');

    return {
      baseline: baselineVal,
      target: targetVal,
      pixelCount: pixelCount
    };
  }

  // Calculate for both countries
  const namibiaStats = calculateAnomalyStats(namibia, 'Namibia');
  const zimbabweStats = calculateAnomalyStats(zimbabwe, 'Zimbabwe');

  const namibiaBaseline = namibiaStats.baseline.getInfo();
  const namibiaTarget = namibiaStats.target.getInfo();
  const namibiaPixels = namibiaStats.pixelCount.getInfo();

  const zimbabweBaseline = zimbabweStats.baseline.getInfo();
  const zimbabweTarget = zimbabweStats.target.getInfo();
  const zimbabwePixels = zimbabweStats.pixelCount.getInfo();

  print(`Namibia - Baseline NDVI: ${namibiaBaseline?.toFixed(3)}, 2019 NDVI: ${namibiaTarget?.toFixed(3)}, Pixels: ${namibiaPixels}`);
  print(`Zimbabwe - Baseline NDVI: ${zimbabweBaseline?.toFixed(3)}, 2019 NDVI: ${zimbabweTarget?.toFixed(3)}, Pixels: ${zimbabwePixels}`);

  // Check for valid pixels
  if (namibiaPixels === 0 || zimbabwePixels === 0) {
    print("<answer>C2</answer>");
    return;
  }

  // Check for calculation failures
  if (namibiaBaseline === null || namibiaTarget === null || 
      zimbabweBaseline === null || zimbabweTarget === null ||
      isNaN(namibiaBaseline) || isNaN(namibiaTarget) ||
      isNaN(zimbabweBaseline) || isNaN(zimbabweTarget)) {
    print("<answer>C3</answer>");
    return;
  }

  // Validate NDVI range
  if (namibiaBaseline < -1 || namibiaBaseline > 1 || namibiaTarget < -1 || namibiaTarget > 1 ||
      zimbabweBaseline < -1 || zimbabweBaseline > 1 || zimbabweTarget < -1 || zimbabweTarget > 1) {
    print("<answer>C3</answer>");
    return;
  }

  // Calculate anomalies (negative means worse vegetation)
  const namibiaAnomaly = (namibiaTarget - namibiaBaseline) / namibiaBaseline;
  const zimbabweAnomaly = (zimbabweTarget - zimbabweBaseline) / zimbabweBaseline;

  print(`Namibia anomaly: ${(namibiaAnomaly * 100).toFixed(1)}%`);
  print(`Zimbabwe anomaly: ${(zimbabweAnomaly * 100).toFixed(1)}%`);

  // Determine if Namibia anomaly is worse (more negative)
  if (namibiaAnomaly < zimbabweAnomaly) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
